async(page)=>{
 const base='http://127.0.0.1:5173/',checks=[],errors=[],cloudCalls=[];let backup,failure=''
 const check=(ok,label)=>{if(!ok)throw Error(label);checks.push(label)},error=e=>errors.push(e.message),request=r=>{if(/cloudbasegateway|tcb-api|tencentcloudapi/.test(r.url()))cloudCalls.push(r.url())},nav=async(route,bulk=false)=>{await page.goto(base+'?extra='+Date.now()+'&demo=admin'+(bulk?'&reviewCase=bulk':'')+'#/'+route);await page.locator('main').waitFor()}
 page.on('pageerror',error);page.on('request',request);page.setDefaultTimeout(12000)
 try{
  await nav('publish/demo-food-1');await page.getByLabel('食物 / 饮品名称').waitFor();backup=await page.evaluate(()=>Object.fromEntries(Object.keys(localStorage).filter(k=>k.startsWith('xsyj-')).map(k=>[k,localStorage.getItem(k)])));await page.setViewportSize({width:390,height:844});await page.locator('.photo-grid').scrollIntoViewIfNeeded();let buttons=page.locator('.photo-grid .photo-preview'),before=await buttons.locator('img').evaluateAll(rows=>rows.map(i=>i.getAttribute('src'))),a=await buttons.nth(1).boundingBox(),b=await buttons.first().boundingBox();await page.mouse.move(a.x+a.width/2,a.y+a.height/2);await page.mouse.down();await page.waitForTimeout(420);await page.mouse.move(b.x+b.width/2,b.y+b.height/2,{steps:8});await page.keyboard.press('Escape');await page.mouse.up();await page.waitForTimeout(100);check(JSON.stringify(before)===JSON.stringify(await buttons.locator('img').evaluateAll(rows=>rows.map(i=>i.getAttribute('src')))),'Esc取消拖动恢复原顺序');check(await page.locator('.photo-drag-ghost').count()===0,'取消后清除拖动浮层')
  a=await buttons.nth(1).boundingBox();await page.mouse.move(a.x+a.width/2,a.y+a.height/2);await page.mouse.down();await page.mouse.move(a.x+a.width/2+18,a.y+a.height/2,{steps:1});await page.waitForTimeout(430);check(await page.locator('.photo-drag-ghost').count()===0,'长按前滑动超过阈值不抢占页面滚动');await page.mouse.up();await page.getByRole('button',{name:'调整第2张照片顺序',exact:true}).focus();await page.keyboard.press('Enter');await page.getByRole('button',{name:'前移',exact:true}).focus();await page.keyboard.press('Enter');await page.waitForTimeout(100);check(await buttons.first().locator('img').getAttribute('src')===before[1],'键盘可以通过排序菜单换序')
  before=await buttons.locator('img').evaluateAll(rows=>rows.map(i=>i.getAttribute('src')));a=await buttons.nth(1).boundingBox();b=await buttons.first().boundingBox();const cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});try{await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:a.x+a.width/2,y:a.y+a.height/2}]});await page.waitForTimeout(430);check(await page.locator('.photo-drag-ghost').count()===1,'Chromium触摸模拟可长按进入拖动');await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:b.x+b.width/2,y:b.y+b.height/2}]});await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await page.waitForTimeout(100);check(await buttons.first().locator('img').getAttribute('src')===before[1],'触摸拖动松手完成排序');check(await page.getByRole('dialog',{name:'照片预览',exact:true}).count()===0,'触摸排序不会误触图片预览')}finally{await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});await cdp.detach()}
  await nav('review-admin?kind=reply&id=bulk-reply-0',true);await page.locator('.review-selected').waitFor();await page.locator('.review-operation').getByRole('button',{name:'需修改',exact:true}).click();await page.getByLabel('审核处理意见',{exact:true}).fill('请补充本层回复的具体事实。');await page.locator('.review-operation').getByRole('button',{name:'保存审核结果',exact:true}).click();await page.getByRole('status').waitFor();await nav('messages',true);await page.getByRole('heading',{name:'互动消息',exact:true}).waitFor();await page.locator('article.message').filter({hasText:'请补充本层回复的具体事实。'}).getByRole('button',{name:'按要求修改 →',exact:true}).click();await page.getByRole('heading',{name:'修改第1楼',exact:true}).waitFor();check(true,'楼层修改通知能直接打开本人原楼层编辑');await page.getByLabel('修改楼层正文',{exact:true}).fill('已补充本层回复的具体时间和事实。');await page.getByRole('button',{name:'提交楼层修改',exact:true}).click();await page.locator('#forum-floor-1').waitFor();check(await page.locator('#forum-floor-1 .review-badge').innerText()==='待审核','原楼层修改后进入待审核');check((await page.locator('#forum-floor-1').innerText()).includes('隐藏'),'原楼层修改后不会自行恢复公开');check(await page.locator('.forum-floor').count()===10,'修改楼层不新增或改变其他楼号')
  check(errors.length===0,'补充交互无运行时错误');check(cloudCalls.length===0,'补充案例无真实云端请求')
 }catch(e){failure=e.message}finally{await page.mouse.up().catch(()=>{});if(backup)await page.evaluate(old=>{for(const k of Object.keys(localStorage))if(k.startsWith('xsyj-'))localStorage.removeItem(k);for(const[k,v]of Object.entries(old))localStorage.setItem(k,v)},backup);page.off('pageerror',error);page.off('request',request);page.setDefaultTimeout(30000)}
 return {base,checks,errors,cloudCalls,failure,touchMode:'Chromium模拟，非实体机'}
}
